// Secure Express.js Application
// This version implements security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const basicAuth = require('express-basic-auth');
const { body, validationResult } = require('express-validator');
require('dotenv').config();

const app = express();

// ======================
// SECURITY CONFIGURATION
// ======================

// 1. Security Headers (Helmet)
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", "data:", "https:"],
            connectSrc: ["'self'"],
            fontSrc: ["'self'"],
            objectSrc: ["'none'"],
            mediaSrc: ["'self'"],
            frameSrc: ["'none'"],
        },
    },
    hsts: {
        maxAge: 31536000,
        includeSubDomains: true,
        preload: true
    }
}));

// 2. Request Logging
app.use(morgan('combined'));

// 3. Rate Limiting
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
});
app.use(limiter);

// 4. Body Parsing with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Remove X-Powered-By header
app.disable('x-powered-by');

// ======================
// ROUTES WITH SECURITY
// ======================

// Health check endpoint (public)
app.get('/health', [
    // Input validation
    body().custom(() => true), // No body expected
], (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
    }

    res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        environment: process.env.NODE_ENV || 'development'
    });
});

// Users endpoint (protected with authentication)
const usersAuth = basicAuth({
    users: { 
        [process.env.ADMIN_USER || 'admin']: process.env.ADMIN_PASSWORD || 'secure_password_here' 
    },
    challenge: true,
    unauthorizedResponse: (req) => {
        return { error: 'Authentication required', timestamp: new Date().toISOString() };
    }
});

app.get('/users', usersAuth, [
    // Add query parameter validation if needed
], (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
    }

    // Return user data (in production, this would come from a database)
    // Note: Email addresses are masked for privacy
    res.json([
        { 
            id: 1, 
            name: 'Alice', 
            email: 'a***e@example.com', // Masked for privacy
            role: 'user' 
        },
        { 
            id: 2, 
            name: 'Bob', 
            email: 'b**@example.com', // Masked for privacy
            role: 'user' 
        },
    ]);
});

// Demo endpoint with parameter validation
app.get('/search', [
    // Validate query parameters
    body('query').optional().isString().trim().escape(),
    body('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
], (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
    }

    const { query = '', limit = 10 } = req.query;

    res.json({
        message: 'Search endpoint',
        query: query, // Already sanitized by express-validator
        limit: limit,
        results: []
    });
});

// ======================
// ERROR HANDLING
// ======================

// 404 handler
app.use((req, res, next) => {
    res.status(404).json({
        error: 'Not found',
        path: req.path,
        method: req.method,
        timestamp: new Date().toISOString()
    });
});

// Global error handler
app.use((err, req, res, next) => {
    console.error('Error:', {
        message: err.message,
        stack: err.stack,
        path: req.path,
        method: req.method,
        timestamp: new Date().toISOString()
    });

    // Don't expose stack traces in production
    const isProduction = process.env.NODE_ENV === 'production';

    res.status(err.status || 500).json({
        error: isProduction ? 'Internal server error' : err.message,
        ...(isProduction ? {} : { stack: err.stack }),
        timestamp: new Date().toISOString()
    });
});

// ======================
// SERVER CONFIGURATION
// ======================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '127.0.0.1';

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

// Graceful shutdown
process.on('SIGTERM', () => {
    console.log('SIGTERM received. Shutting down gracefully...');
    process.exit(0);
});

process.on('SIGINT', () => {
    console.log('SIGINT received. Shutting down gracefully...');
    process.exit(0);
});

// Start server
if (require.main === module) {
    app.listen(PORT, HOST, () => {
        console.log(`
========================================
Secure Express Server
========================================
Environment: ${process.env.NODE_ENV || 'development'}
Server: http://${HOST}:${PORT}
Health Check: http://${HOST}:${PORT}/health
Time: ${new Date().toISOString()}
========================================
        `);
    });
}

module.exports = app;

