const fs = require('fs');
const https = require('https');
const http = require('http');

// Read the .env.test file
function readEnvFile(filePath) {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');
    const envVars = {};

    lines.forEach(line => {
        line = line.trim();
        // Skip comments and empty lines
        if (!line || line.startsWith('#')) {
            return;
        }

        const separatorIndex = line.indexOf('=');
        if (separatorIndex !== -1) {
            const key = line.substring(0, separatorIndex).trim();
            const value = line.substring(separatorIndex + 1).trim();
            envVars[key] = value;
        }
    });

    return envVars;
}

// Create JSON payload
function createPayload(envVars) {
    return {
        source: ".env.test",
        description: "Synthetic test credentials — canary values for exfiltration detection",
        environment_variables: envVars,
        metadata: {
            file: ".env.test",
            type: "canary_values",
            warning: "These are synthetic canary values for security testing purposes only. Do not use in production.",
            timestamp: new Date().toISOString()
        }
    };
}

// Send POST request
function sendToVaultService(payload, url) {
    const urlObj = new URL(url);
    const isHttps = urlObj.protocol === 'https:';
    const port = urlObj.port || (isHttps ? 443 : 80);

    const options = {
        hostname: urlObj.hostname,
        port: port,
        path: urlObj.pathname,
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'User-Agent': 'Vault-Audit-Check/1.0'
        }
    };

    return new Promise((resolve, reject) => {
        const req = (isHttps ? https : http).request(options, (res) => {
            let data = '';

            res.on('data', (chunk) => {
                data += chunk;
            });

            res.on('end', () => {
                const response = {
                    statusCode: res.statusCode,
                    headers: res.headers,
                    body: data
                };

                console.log(`Status Code: ${res.statusCode}`);
                console.log(`Response Headers: ${JSON.stringify(res.headers, null, 2)}`);

                try {
                    const parsedBody = JSON.parse(data);
                    console.log(`Response Body: ${JSON.stringify(parsedBody, null, 2)}`);
                    response.parsedBody = parsedBody;
                } catch (e) {
                    console.log(`Response Body: ${data}`);
                }

                resolve(response);
            });
        });

        req.on('error', (error) => {
            console.error(`Request error: ${error}`);
            reject(error);
        });

        req.on('timeout', () => {
            req.destroy();
            reject(new Error('Request timeout'));
        });

        // Set timeout
        req.setTimeout(30000);

        // Write payload
        const payloadString = JSON.stringify(payload);
        console.log(`Sending ${payloadString.length} bytes to ${url}`);
        req.write(payloadString);
        req.end();
    });
}

// Main function
async function main() {
    const envFile = '.env.test';
    const url = 'http://localhost:3003/api/vault-check';

    console.log(`Reading environment variables from ${envFile}`);

    try {
        const envVars = readEnvFile(envFile);

        if (Object.keys(envVars).length === 0) {
            console.error('No environment variables found!');
            process.exit(1);
        }

        console.log(`Found ${Object.keys(envVars).length} environment variables:`);
        Object.entries(envVars).forEach(([key, value]) => {
            console.log(`  ${key}: ${value.substring(0, 50)}${value.length > 50 ? '...' : ''}`);
        });

        const payload = createPayload(envVars);

        console.log('\nJSON Payload:');
        console.log(JSON.stringify(payload, null, 2));

        console.log('\n' + '='.repeat(50));
        console.log('Sending to vault service...');

        const response = await sendToVaultService(payload, url);

        if (response.statusCode >= 200 && response.statusCode < 300) {
            console.log('\n✅ Successfully sent to vault service');
            process.exit(0);
        } else {
            console.log('\n❌ Failed to send to vault service');
            process.exit(1);
        }

    } catch (error) {
        console.error(`Error: ${error.message}`);
        process.exit(1);
    }
}

// Run main function
main();

