  windowMs: config.security.rateLimit.windowMs,
  max: config.security.rateLimit.max,
  message: config.security.rateLimit.message,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// CORS from config
app.use(cors({
  origin: config.security.cors.origin,
  credentials: config.security.cors.credentials,
}));

// Response compression
app.use(compression());

// Disable X-Powered-By header
app.disable('x-powered-by');

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: config.server.environment,
    appName: config.app.name,
    appVersion: config.app.version,
  });
});

// Users endpoint - loaded from environment or external source
app.get('/users', (req, res) => {
  // In a real application, users would come from a database
  // For demonstration, we're returning minimal data
  // You could load users from an environment variable or external API

  // Example: Load from environment variable (for demo only)
  // const usersJson = process.env.DEMO_USERS || '[]';
  // const users = JSON.parse(usersJson);

  // For now, returning basic demo data
  const users = [
    { id: 1, name: 'Demo User 1' },
    { id: 2, name: 'Demo User 2' },
  ];

  // Apply pagination from config
  const page = parseInt(req.query.page, 10) || 1;
  const limit = parseInt(req.query.limit, 10) || config.app.defaultPageSize;

  const startIndex = (page - 1) * limit;
  const endIndex = page * limit;
  const paginatedUsers = users.slice(startIndex, endIndex);

  res.json({
    users: paginatedUsers,
    pagination: {
      page,
      limit,
      total: users.length,
      totalPages: Math.ceil(users.length / limit),
    }
  });
});

// Custom 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found'
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't expose sensitive error details in production
  const errorResponse = {
    error: 'Internal Server Error',
    message: config.server.environment === 'development' ? err.message : 'Something went wrong',
    requestId: req.id,
  };

  res.status(err.status || 500).json(errorResponse);
});

// Start server with config values
const server = app.listen(config.server.port, config.server.host, () => {
  console.log(`
╔══════════════════════════════════════╗
║   ${config.app.name} v${config.app.version}   ║
╠══════════════════════════════════════╣
║  Environment: ${config.server.environment.padEnd(12)} ║
║  Server Port: ${config.server.port.toString().padEnd(13)} ║
║  Server Host: ${config.server.host.padEnd(13)} ║
║  Rate Limit:  ${config.security.rateLimit.max} req/${config.security.rateLimit.windowMs / 60000}min ║
╚══════════════════════════════════════╝
`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

#!/usr/bin/env node
// Script to detect hardcoded values in JavaScript files

const fs = require('fs');
const path = require('path');

// Patterns to detect hardcoded values that should be environment variables
const patterns = [
  // Port numbers
  { regex: /(?:port|PORT)\s*[:=]\s*['"]?(\d{4,5})['"]?/gi, type: 'PORT_NUMBER', description: 'Hardcoded port number' },

  // Common service ports
  { regex: /['"]?(?:3000|8080|9000|5000|8000|4000)['"]?/g, type: 'COMMON_PORT', description: 'Common hardcoded port' },

  // Database URLs
  { regex: /(?:mongodb|postgres|mysql|redis):\/\/[^'"]+/gi, type: 'DB_URL', description: 'Hardcoded database URL' },

  // API keys/secret patterns
  { regex: /['"](?:sk_|pk_|AKIA|GITHUB_|SECRET_|KEY_|TOKEN_|PASSWORD)[A-Za-z0-9_\-]{10,}['"]/gi, type: 'API_KEY', description: 'Possible API key or secret' },

  // Email addresses in code
  { regex: /['"][A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}['"]/gi, type: 'EMAIL', description: 'Hardcoded email address' },

  // URLs and endpoints
  { regex: /['"](?:https?:\/\/|wss?:\/\/)[^'"]+['"]/gi, type: 'URL', description: 'Hardcoded URL' },

  // Localhost references
  { regex: /['"](?:localhost|127\.0\.0\.1|0\.0\.0\.0)['"]/gi, type: 'LOCALHOST', description: 'Hardcoded localhost reference' },

  // Common config values
  { regex: /(?:timeout|TIMEOUT)\s*[:=]\s*['"]?\d+['"]?/gi, type: 'TIMEOUT', description: 'Hardcoded timeout value' },
  { regex: /(?:max|MAX|limit|LIMIT)\s*[:=]\s*['"]?\d+['"]?/gi, type: 'LIMIT', description: 'Hardcoded limit value' },
];

function detectHardcodedValues(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    const findings = [];

    lines.forEach((line, index) => {
      const lineNumber = index + 1;
      const trimmedLine = line.trim();

      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('//') || trimmedLine.startsWith('/*')) {
        return;
      }

      patterns.forEach(pattern => {
        const matches = line.match(pattern.regex);
        if (matches) {
          matches.forEach(match => {
            findings.push({
              file: path.basename(filePath),
              line: lineNumber,
              type: pattern.type,
              description: pattern.description,
              value: match,
              context: trimmedLine.slice(0, 100), // First 100 chars for context
            });
          });
        }
      });
    });

    return findings;
  } catch (error) {
    console.error(`Error reading file ${filePath}:`, error.message);
    return [];
  }
}

function analyzeFile(filePath) {
  console.log(`\n🔍 Analyzing: ${filePath}`);
  console.log('=' .repeat(80));

  const findings = detectHardcodedValues(filePath);

  if (findings.length === 0) {
    console.log('✅ No hardcoded values detected that should be environment variables.');
    return;
  }

  // Group findings by type
  const groupedFindings = {};
  findings.forEach(finding => {
    if (!groupedFindings[finding.type]) {
      groupedFindings[finding.type] = [];
    }
    groupedFindings[finding.type].push(finding);
  });

  Object.keys(groupedFindings).forEach(type => {
    console.log(`\n📌 ${type}:`);
    console.log('-'.repeat(40));

    groupedFindings[type].forEach(finding => {
      console.log(`  Line ${finding.line}: ${finding.value}`);
      console.log(`  Context: ${finding.context}`);
      console.log(`  File: ${finding.file}`);
      console.log();
    });
  });

  console.log(`\n📊 Summary for ${filePath}:`);
  console.log(`Total findings: ${findings.length}`);

  const criticalCount = findings.filter(f => 
    ['PORT_NUMBER', 'DB_URL', 'API_KEY'].includes(f.type)
  ).length;

  if (criticalCount > 0) {
    console.log(`⚠️  Critical findings: ${criticalCount} (should be environment variables)`);
  }
}

// Main execution
if (require.main === module) {
  const filesToAnalyze = process.argv.slice(2);

  if (filesToAnalyze.length === 0) {
    console.log('Usage: node detect_hardcoded.js <file1.js> <file2.js> ...');
    console.log('Example: node detect_hardcoded.js app.js');
    process.exit(1);
  }

  console.log('🚀 Hardcoded Value Detection Tool');
  console.log('='.repeat(80));
  console.log('Looking for values that should be environment variables...\n');

  filesToAnalyze.forEach(file => {
    if (fs.existsSync(file)) {
      analyzeFile(file);
    } else {
      console.error(`❌ File not found: ${file}`);
    }
  });
}

module.exports = { detectHardcodedValues, analyzeFile };

