// Secure version of Express.js application with basic security measures

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// Security headers - reduces attack surface
app.use(helmet());

// Rate limiting - prevents brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Environment-based configuration
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Basic request logging (without sensitive data)
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.url}`);
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV 
  });
});

// Users endpoint with input validation example
app.get('/users', (req, res) => {
  // Example of parameter validation
  const { limit } = req.query;

  if (limit && (isNaN(limit) || parseInt(limit) > 100)) {
    return res.status(400).json({ 
      error: 'Invalid limit parameter. Must be a number ≤ 100' 
    });
  }

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply limit if provided and valid
  const result = limit ? users.slice(0, parseInt(limit)) : users;
  res.json(result);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err.message);

  // Don't expose stack traces in production
  const errorResponse = NODE_ENV === 'development' 
    ? { error: err.message, stack: err.stack }
    : { error: 'An internal server error occurred' };

  res.status(500).json(errorResponse);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

app.listen(PORT, () => {
  console.log(`Server running in ${NODE_ENV} mode on port ${PORT}`);
});

module.exports = app;

