// Configuration module for managing environment-specific settings
// All sensitive and environment-specific values should be configured here

const Joi = require('joi'); // Would need to be installed for validation

/**
 * Configuration schema for validation
 */
const configSchema = Joi.object({
  // Server configuration
  server: Joi.object({
    port: Joi.number().port().default(3000),
    env: Joi.string().valid('development', 'production', 'test').default('production'),
    host: Joi.string().hostname().default('0.0.0.0')
  }).required(),

  // Security configuration
  security: Joi.object({
    rateLimit: Joi.object({
      windowMs: Joi.number().min(60000).default(15 * 60 * 1000), // 15 minutes default
      max: Joi.number().min(1).default(100),
      message: Joi.string().default('Too many requests from this IP, please try again later.')
    }).required(),

    maxQueryLimit: Joi.number().min(1).default(100),

    // CORS configuration
    cors: Joi.object({
      origin: Joi.string().default('*'),
      methods: Joi.string().default('GET,POST,PUT,DELETE,OPTIONS'),
      allowedHeaders: Joi.string().default('Content-Type,Authorization')
    }).default()
  }).required(),

  // Database configuration
  database: Joi.object({
    url: Joi.string().uri().required(),
    pool: Joi.object({
      min: Joi.number().min(1).default(2),
      max: Joi.number().min(1).default(10)
    }).default()
  }),

  // API configuration
  api: Joi.object({
    version: Joi.string().default('v1'),
    prefix: Joi.string().default('/api'),
    timeout: Joi.number().min(1000).default(30000)
  }).default(),

  // Logging configuration
  logging: Joi.object({
    level: Joi.string().valid('error', 'warn', 'info', 'debug').default('info'),
    format: Joi.string().valid('json', 'simple').default('json'),
    dir: Joi.string().default('./logs')
  }).default()
});

/**
 * Load configuration from environment variables
 */
function loadConfig() {
  const config = {
    server: {
      port: process.env.PORT || 3000,
      env: process.env.NODE_ENV || 'production',
      host: process.env.HOST || '0.0.0.0'
    },

    security: {
      rateLimit: {
        windowMs: process.env.RATE_LIMIT_WINDOW_MS || (15 * 60 * 1000),
        max: process.env.RATE_LIMIT_MAX || 100,
        message: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later.'
      },

      maxQueryLimit: process.env.MAX_QUERY_LIMIT || 100,

      cors: {
        origin: process.env.CORS_ORIGIN || '*',
        methods: process.env.CORS_METHODS || 'GET,POST,PUT,DELETE,OPTIONS',
        allowedHeaders: process.env.CORS_ALLOWED_HEADERS || 'Content-Type,Authorization'
      }
    },

    database: process.env.DATABASE_URL ? {
      url: process.env.DATABASE_URL,
      pool: {
        min: process.env.DB_POOL_MIN || 2,
        max: process.env.DB_POOL_MAX || 10
      }
    } : undefined,

    api: {
      version: process.env.API_VERSION || 'v1',
      prefix: process.env.API_PREFIX || '/api',
      timeout: process.env.API_TIMEOUT || 30000
    },

    logging: {
      level: process.env.LOG_LEVEL || 'info',
      format: process.env.LOG_FORMAT || 'json',
      dir: process.env.LOG_DIR || './logs'
    }
  };

  // Validate configuration
  const { error, value } = configSchema.validate(config, { abortEarly: false });

  if (error) {
    console.error('Configuration validation error:');
    error.details.forEach(detail => {
      console.error(`  - ${detail.path.join('.')}: ${detail.message}`);
    });
    throw new Error('Invalid configuration');
  }

  return value;
}

/**
 * Get environment-specific configuration
 */
function getConfig(env = process.env.NODE_ENV || 'production') {
  const baseConfig = loadConfig();

  // Environment-specific overrides
  const environmentOverrides = {
    development: {
      logging: { level: 'debug', format: 'simple' },
      security: { rateLimit: { max: 1000 } } // More lenient in development
    },

    test: {
      logging: { level: 'error' },
      security: { rateLimit: { max: 5000 } } // Even more lenient in tests
    },

    production: {
      logging: { level: 'info', format: 'json' },
      security: { 
        rateLimit: { max: 100 },
        cors: { origin: process.env.CORS_ORIGIN || 'https://yourdomain.com' }
      }
    }
  };

  const override = environmentOverrides[env] || {};
  return { ...baseConfig, ...override };
}

module.exports = {
  loadConfig,
  getConfig,
  configSchema
};

// Simple configuration module without external dependencies
// All hardcoded values should be moved to environment variables

/**
 * Simple configuration validation
 */
function validateConfig(config) {
  const errors = [];

  // Validate server port
  if (config.server.port < 1 || config.server.port > 65535) {
    errors.push('Server port must be between 1 and 65535');
  }

  // Validate environment
  const validEnvs = ['development', 'production', 'test'];
  if (!validEnvs.includes(config.server.env)) {
    errors.push(`Environment must be one of: ${validEnvs.join(', ')}`);
  }

  // Validate rate limit values
  if (config.security.rateLimit.windowMs < 1000) {
    errors.push('Rate limit window must be at least 1000ms');
  }

  if (config.security.rateLimit.max < 1) {
    errors.push('Rate limit max requests must be at least 1');
  }

  if (config.security.maxQueryLimit < 1) {
    errors.push('Max query limit must be at least 1');
  }

  return errors;
}

/**
 * Load configuration from environment variables with defaults
 */
function loadConfig() {
  const config = {
    server: {
      port: parseInt(process.env.PORT || '3000', 10),
      env: process.env.NODE_ENV || 'production',
      host: process.env.HOST || '0.0.0.0'
    },

    security: {
      rateLimit: {
        windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS || `${15 * 60 * 1000}`, 10), // 15 minutes default
        max: parseInt(process.env.RATE_LIMIT_MAX || '100', 10),
        message: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later.'
      },

      maxQueryLimit: parseInt(process.env.MAX_QUERY_LIMIT || '100', 10),

      cors: {
        origin: process.env.CORS_ORIGIN || '*',
        methods: process.env.CORS_METHODS || 'GET,POST,PUT,DELETE,OPTIONS',
        allowedHeaders: process.env.CORS_ALLOWED_HEADERS || 'Content-Type,Authorization'
      }
    },

    api: {
      version: process.env.API_VERSION || 'v1',
      prefix: process.env.API_PREFIX || '/api',
      timeout: parseInt(process.env.API_TIMEOUT || '30000', 10)
    },

    logging: {
      level: process.env.LOG_LEVEL || 'info',
      format: process.env.LOG_FORMAT || 'json',
      dir: process.env.LOG_DIR || './logs'
    }
  };

  // Apply environment-specific defaults
  if (config.server.env === 'development') {
    config.logging.level = 'debug';
    config.logging.format = 'simple';
    config.security.rateLimit.max = 1000; // More lenient in development
  } else if (config.server.env === 'test') {
    config.logging.level = 'error';
    config.security.rateLimit.max = 5000; // Very lenient in tests
  }

  // Validate configuration
  const errors = validateConfig(config);
  if (errors.length > 0) {
    console.error('Configuration errors:');
    errors.forEach(error => console.error(`  - ${error}`));
    throw new Error('Invalid configuration');
  }

  return config;
}

/**
 * Get configuration for current environment
 */
module.exports = loadConfig();

