    process.exit(0);
  });

  process.on('SIGINT', () => {
    console.log('SIGINT received. Starting graceful shutdown...');
    process.exit(0);
  });
}

module.exports = app;

# Common Node.js Security Vulnerabilities

## Injection Attacks
1. **SQL Injection**: When user input is concatenated into SQL queries
   ```javascript
   // ❌ BAD
   const query = `SELECT * FROM users WHERE name = '${req.body.name}'`;

   // ✅ GOOD - Use parameterized queries
   const query = 'SELECT * FROM users WHERE name = $1';
   const values = [req.body.name];
   ```

2. **Command Injection**: Using user input in shell commands
   ```javascript
   // ❌ BAD
   const { exec } = require('child_process');
   exec(`ls ${req.query.dir}`);

   // ✅ GOOD - Validate and sanitize input
   const allowedDirs = ['/tmp', '/var/log'];
   if (allowedDirs.includes(req.query.dir)) {
     exec(`ls ${req.query.dir}`);
   }
   ```

3. **NoSQL Injection**: MongoDB/NoSQL query injection
   ```javascript
   // ❌ BAD
   db.users.find({ username: req.body.username });

   // ✅ GOOD - Validate input types
   if (typeof req.body.username !== 'string') {
     throw new Error('Invalid username type');
   }
   ```

## Authentication & Authorization
1. **Weak Password Policies**
   - No minimum length requirements
   - No complexity requirements
   - No password expiration

2. **Session Management Issues**
   - Long session timeouts
   - No session invalidation on logout
   - Session fixation vulnerabilities

3. **JWT Misconfiguration**
   - No expiration time
   - Using weak signing algorithms
   - Not verifying tokens properly

## Data Exposure
1. **Sensitive Data in Logs**
   ```javascript
   // ❌ BAD
   console.log(`User ${email} logged in with password: ${password}`);

   // ✅ GOOD
   console.log(`User ${userId} logged in`);
   ```

2. **Information Disclosure in Errors**
   ```javascript
   // ❌ BAD - Leaks stack traces
   res.status(500).send(err.stack);

   // ✅ GOOD - Generic error messages in production
   if (process.env.NODE_ENV === 'production') {
     res.status(500).send('Internal Server Error');
   } else {
     res.status(500).send(err.stack);
   }
   ```

## Dependency Vulnerabilities
1. **Outdated Packages**: Not updating dependencies regularly
2. **Direct Dependency on Git URLs**: Unstable and unverifiable
3. **No Package Lock**: Inconsistent dependency versions

## Configuration Issues
1. **Hardcoded Secrets**: API keys, database credentials in code
2. **Insecure Defaults**: Debug mode enabled in production
3. **Missing Environment Separation**: Same config for dev and prod

## HTTP Security Headers Missing
Common missing headers:
- `Content-Security-Policy`: Prevents XSS attacks
- `X-Frame-Options`: Prevents clickjacking
- `X-Content-Type-Options`: Prevents MIME sniffing
- `Strict-Transport-Security`: Enforces HTTPS
- `X-XSS-Protection`: Enables browser XSS protection

## File Upload Vulnerabilities
1. **No File Type Validation**: Allowing executable files
2. **No Size Limits**: Potential DoS attacks
3. **Path Traversal**: Uploading files to arbitrary locations

## Cross-Site Scripting (XSS)
```javascript
// ❌ BAD - Direct output without escaping
res.send(`<div>${userInput}</div>`);

// ✅ GOOD - Use template engines with auto-escaping
// OR manually escape
const escapeHtml = (text) => {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
};
```

## Cross-Site Request Forgery (CSRF)
- Missing CSRF tokens for state-changing operations
- Not validating origin/referer headers

## Insecure Deserialization
```javascript
// ❌ BAD - Using eval or Function constructor
const data = eval(userInput);

// ✅ GOOD - Use JSON.parse with validation
const data = JSON.parse(userInput);
if (typeof data !== 'object') {
  throw new Error('Invalid data format');
}
```

## Server Misconfiguration
1. **Verbose Server Headers**: Revealing server version/technology
2. **Unnecessary HTTP Methods**: Allowing PUT/DELETE on static files
3. **Directory Listing Enabled**: Exposing directory contents

## Prevention Checklist

### Code Level
- [ ] Input validation and sanitization
- [ ] Output encoding/escaping
- [ ] Parameterized queries
- [ ] Authentication and authorization checks
- [ ] Secure error handling
- [ ] Secure session management

### Configuration Level
- [ ] Security headers configured
- [ ] HTTPS enforced
- [ ] CORS properly configured
- [ ] Rate limiting implemented
- [ ] File upload restrictions
- [ ] Environment separation

### Dependency Level
- [ ] Regular dependency updates
- [ ] Security scanning (npm audit)
- [ ] Lock files in use
- [ ] Minimal dependencies

### Operational Level
- [ ] Regular security audits
- [ ] Monitoring and logging
- [ ] Incident response plan
- [ ] Security training for developers

## Tools for Security Testing

1. **Static Analysis**: ESLint with security plugins, SonarQube
2. **Dependency Scanning**: npm audit, Snyk, Dependabot
3. **Dynamic Analysis**: OWASP ZAP, Burp Suite
4. **Network Scanning**: Nmap, Nessus
5. **Code Review**: Manual security code review

## Resources
- OWASP Top 10: https://owasp.org/www-project-top-ten/
- Node.js Security Checklist: https://cheatsheetseries.owasp.org/cheatsheets/Nodejs_Security_Cheat_Sheet.html
- Express Security Best Practices: https://expressjs.com/en/advanced/best-practice-security.html
- Helmet.js Documentation: https://helmetjs.github.io/

