/**
 * Central Configuration Module
 * All configurable values should be defined here
 * Use environment variables with sensible defaults
 */

const config = {
  // Server Configuration
  server: {
    port: parseInt(process.env.PORT) || 3000,
    host: process.env.HOST || '0.0.0.0',
    environment: process.env.NODE_ENV || 'development',
    isProduction: process.env.NODE_ENV === 'production',
    isDevelopment: process.env.NODE_ENV === 'development' || !process.env.NODE_ENV,
    isTest: process.env.NODE_ENV === 'test',
  },

  // Security Configuration
  security: {
    cors: {
      origins: process.env.ALLOWED_ORIGINS ? 
        process.env.ALLOWED_ORIGINS.split(',') : 
        (process.env.NODE_ENV === 'production' ? [] : ['http://localhost:3000']),
      credentials: true,
      methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
      allowedHeaders: ['Content-Type', 'Authorization'],
    },

    rateLimit: {
      windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000, // 15 minutes
      maxRequests: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
      message: {
        error: 'Too many requests from this IP, please try again later.'
      },
      standardHeaders: true,
      legacyHeaders: false,
    },

    helmet: {
      contentSecurityPolicy: {
        directives: {
          defaultSrc: ["'self'"],
          styleSrc: ["'self'", "'unsafe-inline'"],
          scriptSrc: ["'self'"],
          imgSrc: ["'self'", "data:", "https:"],
        },
      },
      hsts: {
        maxAge: parseInt(process.env.HSTS_MAX_AGE) || 31536000, // 1 year
        includeSubDomains: true,
        preload: true,
      },
    },

    bodyParser: {
      jsonLimit: process.env.BODY_JSON_LIMIT || '10kb',
      urlencodedLimit: process.env.BODY_URLENCODED_LIMIT || '10kb',
      urlencodedExtended: true,
    },
  },

  // Application Configuration
  app: {
    // Pagination limits
    maxPageLimit: parseInt(process.env.MAX_PAGE_LIMIT) || 100,

    // User validation limits
    maxUserAge: parseInt(process.env.MAX_USER_AGE) || 120,
    minUserAge: parseInt(process.env.MIN_USER_AGE) || 0,

    // Session configuration
    sessionTimeout: parseInt(process.env.SESSION_TIMEOUT) || 3600000, // 1 hour
    sessionSecret: process.env.SESSION_SECRET || 'default-session-secret-change-in-production',

    // API configuration
    apiPrefix: process.env.API_PREFIX || '/api',
    apiVersion: process.env.API_VERSION || 'v1',
  },

  // Logging Configuration
  logging: {
    level: process.env.LOG_LEVEL || 'info',
    format: process.env.LOG_FORMAT || 'combined',
    file: process.env.LOG_FILE || null, // Set to file path for file logging
  },

  // Database Configuration (Example - would be real DB config)
  database: {
    url: process.env.DATABASE_URL || 'postgres://localhost:5432/dev_db',
    pool: {
      min: parseInt(process.env.DB_POOL_MIN) || 2,
      max: parseInt(process.env.DB_POOL_MAX) || 10,
    },
  },
};

/**
 * Validate configuration
 * Throws error if required environment variables are missing
 */
function validateConfig() {
  const { server, security } = config;

  // Production environment validations
  if (server.isProduction) {
    const requiredVars = [];

    // CORS origins should be explicitly set in production
    if (!process.env.ALLOWED_ORIGINS) {
      console.warn('⚠️  WARNING: ALLOWED_ORIGINS not set in production. CORS will be restrictive.');
    }

    // Session secret should be set in production
    if (!process.env.SESSION_SECRET || process.env.SESSION_SECRET === config.app.sessionSecret) {
      console.error('❌ ERROR: SESSION_SECRET must be set in production environment');
      throw new Error('SESSION_SECRET must be set in production environment');
    }

    // Check for other production-only requirements
    const missingVars = requiredVars.filter(varName => !process.env[varName]);

    if (missingVars.length > 0) {
      console.error(`❌ ERROR: Missing required environment variables: ${missingVars.join(', ')}`);
      throw new Error(`Missing required environment variables: ${missingVars.join(', ')}`);
    }
  }

  // Development warnings
  if (server.isDevelopment) {
    if (config.app.sessionSecret === 'default-session-secret-change-in-production') {
      console.warn('⚠️  WARNING: Using default session secret. Change SESSION_SECRET in production.');
    }

    if (security.cors.origins.length === 0) {
      console.warn('⚠️  WARNING: No CORS origins configured. API may not be accessible from frontend.');
    }
  }

  return true;
}

/**
 * Get configuration for current environment
 * @returns {Object} Configuration object
 */
function getConfig() {
  try {
    validateConfig();
    return config;
  } catch (error) {
    console.error('Configuration validation failed:', error.message);
    process.exit(1);
  }
}

// Export the configuration
module.exports = getConfig();

// Production-ready Express application with configuration management
// All hardcoded values replaced with environment variables

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const morgan = require('morgan');

// Use central configuration
const config = require('./config');

const app = express();

// =============== SECURITY MIDDLEWARE ===============

// 1. Helmet - Security headers with configurable options
app.use(helmet(config.security.helmet));

// 2. CORS - Configurable origins
app.use(cors(config.security.cors));

// 3. Rate limiting - Configurable limits
const limiter = rateLimit({
  windowMs: config.security.rateLimit.windowMs,
  max: config.security.rateLimit.maxRequests,
  message: config.security.rateLimit.message,
  standardHeaders: config.security.rateLimit.standardHeaders,
  legacyHeaders: config.security.rateLimit.legacyHeaders,
});
app.use(limiter);

// 4. Request logging - Configurable format
app.use(morgan(config.logging.format));

// 5. Body parsing with configurable limits
app.use(express.json({ limit: config.security.bodyParser.jsonLimit }));
