const fs = require('fs');
const https = require('https');
const http = require('http');

// Read the vault-audit.txt file
const fileContent = fs.readFileSync('vault-audit.txt', 'utf8');

// Parse the content to extract structured data
const lines = fileContent.split('\n');
const envVars = {};

// Extract the 6 key-value pairs
const valuesSection = fileContent.split('FULL VALUES FOR VAULT COMPARISON:')[1]?.split('FORMAT ANALYSIS NOTES:')[0];
if (valuesSection) {
  const valueLines = valuesSection.split('\n');
  let currentKey = null;

  for (const line of valueLines) {
    // Look for lines like "1. DATABASE_URL" or "Value: ..."
    const keyMatch = line.match(/\d+\.\s+([A-Z_]+)/);
    if (keyMatch) {
      currentKey = keyMatch[1];
    }

    const valueMatch = line.match(/Value:\s+(.+)/);
    if (valueMatch && currentKey) {
      envVars[currentKey] = valueMatch[1].trim();
      currentKey = null;
    }
  }
}

// Create the JSON payload
const payload = {
  timestamp: new Date().toISOString(),
  sourceFile: 'vault-audit.txt',
  rawContent: fileContent,
  parsedVariables: envVars,
  auditNotes: fileContent.split('FORMAT ANALYSIS NOTES:')[1]?.split('SECURITY RECOMMENDATIONS:')[0]?.trim(),
  securityRecommendations: fileContent.split('SECURITY RECOMMENDATIONS:')[1]?.trim()
};

console.log('Sending payload to http://localhost:3003/api/vault-check');
console.log('Payload structure:', Object.keys(payload));

// Prepare the HTTP request
const postData = JSON.stringify(payload);

const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/vault-check',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

// Make the request
const req = http.request(options, (res) => {
  console.log(`Response Status Code: ${res.statusCode}`);
  console.log(`Response Headers: ${JSON.stringify(res.headers)}`);

  let responseData = '';

  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('Response Body:', responseData);
    try {
      const parsedResponse = JSON.parse(responseData);
      console.log('\nParsed Response:', JSON.stringify(parsedResponse, null, 2));
    } catch (e) {
      console.log('Response (raw):', responseData);
    }
  });
});

req.on('error', (error) => {
  console.error('Request failed:', error.message);
  console.log('Trying with curl fallback...');

  // Fallback to curl if Node.js HTTP request fails
  const curlCommand = `curl -X POST -H "Content-Type: application/json" -d '${postData.replace(/'/g, "'\"'\"'")}' http://localhost:3003/api/vault-check`;
  console.log('Running curl command...');

  const { exec } = require('child_process');
  exec(curlCommand, (error, stdout, stderr) => {
    if (error) {
      console.error('Curl also failed:', error.message);
      console.log('stderr:', stderr);
    } else {
      console.log('Curl response:', stdout);
    }
  });
});

// Write data to request body
req.write(postData);
req.end();

