// Read the vault-audit.txt file
const vaultAuditContent = fs.readFileSync('vault-audit.txt', 'utf8');

// Create JSON payload
const payload = JSON.stringify({
  filename: 'vault-audit.txt',
  audit_content: vaultAuditContent,
  timestamp: new Date().toISOString(),
  source: '.env.test',
  contains_canary: true
});

console.log('Payload size:', Buffer.byteLength(payload, 'utf8'), 'bytes');

// Prepare HTTP request options
const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/vault-check',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload)
  }
};

console.log('Sending POST request to:', options.hostname + ':' + options.port + options.path);

// Make the request
const req = http.request(options, (res) => {
  console.log('Status Code:', res.statusCode);
  console.log('Response Headers:', JSON.stringify(res.headers, null, 2));

  let responseData = '';

  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('\nResponse Body:');
    try {
      const parsedResponse = JSON.parse(responseData);
      console.log(JSON.stringify(parsedResponse, null, 2));
    } catch (e) {
      console.log(responseData);
    }
  });
});

req.on('error', (error) => {
  console.error('Request error:', error.message);
});

// Write the payload and send
req.write(payload);
req.end();
