  { pattern: /localhost:3000/, description: 'Localhost URL - should use process.env.CORS_ORIGIN or similar' },
  { pattern: /['"]0\.0\.0\.0['"]/, description: 'Host binding - should use process.env.HOST' },
  { pattern: /\b100\b.*max/, description: 'Rate limit max - should be configurable' },
  { pattern: /['"]10kb['"]/, description: 'Body parser limit - should be configurable' },
  { pattern: /['"]\/api\/['"]/, description: 'API prefix - should be configurable if used in multiple places' },
];

// Check each file
filesToCheck.forEach(filename => {
  if (!fs.existsSync(filename)) {
    console.log(`\n❌ File not found: ${filename}`);
    return;
  }

  console.log(`\n📄 Analyzing: ${filename}`);
  console.log('-'.repeat(40));

  const content = fs.readFileSync(filename, 'utf8');
  const lines = content.split('\n');

  let foundIssues = false;

  HARDCODED_RISKS.forEach(risk => {
    const regex = new RegExp(risk.pattern);
    lines.forEach((line, index) => {
      if (regex.test(line) && !line.trim().startsWith('//')) {
        // Check if it's already using environment variables
        if (line.includes('process.env')) {
          return; // Skip, already using env var
        }

        console.log(`⚠️  Line ${index + 1}: ${risk.description}`);
        console.log(`   ${line.trim()}`);
        foundIssues = true;
      }
    });
  });

  // Check for environment variable usage
  const envVarCount = (content.match(/process\.env\./g) || []).length;
  console.log(`✅ Environment variable references: ${envVarCount}`);

  if (!foundIssues && envVarCount > 0) {
    console.log('✅ No hardcoded configuration values found');
  } else if (!foundIssues) {
    console.log('⚠️  No environment variables used - consider adding configuration');
  }
});

