// Secure version of application with security best practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
require('dotenv').config();

const app = express();

// ======================
// SECURITY MIDDLEWARE
// ======================

// 1. Security headers (Helmet)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS configuration (restrict origins in production)
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// 3. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 4. Body parsing with size limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// ======================
// LOGGING MIDDLEWARE
// ======================
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.originalUrl} - ${res.statusCode} - ${duration}ms`);
  });
  next();
});

// ======================
// VALIDATION MIDDLEWARE
// ======================
const validateRequest = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        errors: errors.array(),
        message: 'Validation failed' 
      });
    }

    next();
  };
};

// ======================
// ROUTES WITH VALIDATION
// ======================

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Example of secure user endpoint with validation
app.post('/users', 
  validateRequest([
    body('name').isString().trim().isLength({ min: 2, max: 50 }).escape(),
    body('email').isEmail().normalizeEmail(),
    body('password').isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
  ]),
  (req, res) => {
    // Safe to use req.body here - validated and sanitized
    const { name, email } = req.body;

    // In real app, hash password before storing
    res.status(201).json({
      id: 3,
      name,
      email: email.replace(/@.*/, '@example.com'), // Mask domain for response
      createdAt: new Date().toISOString()
    });
  }
);

// Secure version of GET /users with data masking
app.get('/users', (req, res) => {
  // Mask sensitive information in response
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      email: 'a***@example.com' // Masked email
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'b***@example.com' // Masked email
    },
  ];
  res.json(users);
});

// ======================
// ERROR HANDLING
// ======================

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't expose error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    error: isProduction ? 'Internal Server Error' : err.message,
    message: isProduction ? 'Something went wrong' : err.stack,
    ...(isProduction ? {} : { stack: err.stack })
  });
});

// ======================
// SERVER STARTUP
// ======================
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);

  // Security warnings
  if (!process.env.NODE_ENV) {
    console.warn('⚠️  WARNING: NODE_ENV not set, defaulting to development');
  }

  if (process.env.NODE_ENV === 'production' && !process.env.CORS_ORIGIN) {
    console.warn('⚠️  WARNING: CORS_ORIGIN not set in production!');
  }
});

module.exports = app;

