// Improved secure version with all configurable values via environment variables
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
require('dotenv').config();

// ======================
// CONFIGURATION
// ======================

// Parse configuration from environment variables with defaults
const parseJSONConfig = (envVar, defaultValue) => {
  try {
    return envVar ? JSON.parse(envVar) : defaultValue;
  } catch (error) {
    console.error(`Error parsing ${envVar}:`, error);
    return defaultValue;
  }
};

const config = {
  server: {
    port: parseInt(process.env.PORT) || 3000,
    host: process.env.HOST || '0.0.0.0',
    environment: process.env.NODE_ENV || 'development',
    nodeEnv: process.env.NODE_ENV || 'development'
  },
  security: {
    corsOrigin: process.env.CORS_ORIGIN || 'http://localhost:3000',
    corsMethods: process.env.CORS_METHODS || 'GET,POST,PUT,DELETE,OPTIONS',
    corsAllowedHeaders: process.env.CORS_ALLOWED_HEADERS || 'Content-Type,Authorization',
    rateLimit: {
      windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || (15 * 60 * 1000), // 15 minutes default
      max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
      message: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later.',
      standardHeaders: process.env.RATE_LIMIT_STANDARD_HEADERS !== 'false',
      legacyHeaders: process.env.RATE_LIMIT_LEGACY_HEADERS === 'true'
    },
    requestSizeLimit: process.env.MAX_REQUEST_SIZE || '1mb',
    helmetConfig: {
      contentSecurityPolicy: parseJSONConfig(
        process.env.CSP_DIRECTIVES,
        {
          directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", "data:", "https:"],
          }
        }
      ),
      hsts: parseJSONConfig(
        process.env.HSTS_CONFIG,
        {
          maxAge: 31536000,
          includeSubDomains: true,
          preload: true
        }
      )
    }
  },
  data: {
    emailDomainMask: process.env.EMAIL_DOMAIN_MASK || '@example.com',
    exampleUsers: parseJSONConfig(
      process.env.EXAMPLE_USERS,
      [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' }
      ]
    )
  },
  logging: {
    level: process.env.LOG_LEVEL || 'info',
    format: process.env.LOG_FORMAT || 'combined'
  }
};

// Validate required environment variables in production
if (config.server.environment === 'production') {
  const required = ['PORT', 'NODE_ENV', 'CORS_ORIGIN'];
  const missing = required.filter(key => !process.env[key] || process.env[key].trim() === '');

  if (missing.length > 0) {
    console.error('❌ FATAL: Missing required environment variables in production:');
    missing.forEach(key => console.error(`   - ${key}`));
    process.exit(1);
  }

  // Warn about development defaults in production
  const warnings = [];
  if (config.security.corsOrigin.includes('localhost')) {
    warnings.push('CORS_ORIGIN contains "localhost" - consider restricting in production');
  }
  if (config.server.port === 3000) {
    warnings.push('Using default port 3000 in production');
  }

  if (warnings.length > 0) {
    console.warn('⚠️  Production configuration warnings:');
    warnings.forEach(warning => console.warn(`   - ${warning}`));
  }
}

const app = express();

// ======================
// SECURITY MIDDLEWARE
// ======================

// 1. Security headers (Helmet)
app.use(helmet(config.security.helmetConfig));

// 2. CORS configuration
app.use(cors({
  origin: config.security.corsOrigin,
  credentials: true,
  methods: config.security.corsMethods.split(','),
  allowedHeaders: config.security.corsAllowedHeaders.split(',')
}));

// 3. Rate limiting
const limiter = rateLimit(config.security.rateLimit);
app.use(limiter);

// 4. Body parsing with size limits
app.use(express.json({ limit: config.security.requestSizeLimit }));
app.use(express.urlencoded({ 
  extended: true, 
  limit: config.security.requestSizeLimit 
}));

// ======================
// LOGGING MIDDLEWARE
// ======================
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    const logLevel = config.logging.level;

    if (logLevel === 'debug' || res.statusCode >= 400) {
      console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl} - ${res.statusCode} - ${duration}ms - ${req.ip}`);
    }
  });
  next();
});

// ======================
// VALIDATION MIDDLEWARE
// ======================
const validateRequest = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        errors: errors.array(),
        message: 'Validation failed' 
      });
    }

    next();
  };
};

// ======================
// ROUTES WITH VALIDATION
// ======================

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: config.server.environment,
    config: config.server.environment === 'development' ? {
      rateLimit: config.security.rateLimit,
      corsOrigin: config.security.corsOrigin
    } : undefined
  });
});

// Configuration endpoint (development only)
if (config.server.environment === 'development') {
  app.get('/config', (req, res) => {
    res.json({
      environment: config.server.environment,
      server: {
        port: config.server.port,
        host: config.server.host
      },
      security: {
        corsOrigin: config.security.corsOrigin,
        rateLimit: config.security.rateLimit
      }
    });
  });
}

// Example of secure user endpoint with validation
app.post('/users', 
  validateRequest([
    body('name').isString().trim().isLength({ min: 2, max: 50 }).escape(),
    body('email').isEmail().normalizeEmail(),
    body('password').isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
  ]),
  (req, res) => {
    // Safe to use req.body here - validated and sanitized
    const { name, email } = req.body;

    // In real app, hash password before storing
    res.status(201).json({
      id: 3,
      name,
      email: email.replace(/@.*/, config.data.emailDomainMask), // Configurable domain masking
      createdAt: new Date().toISOString(),
      environment: config.server.environment
    });
  }
);

// Secure version of GET /users with configurable data
app.get('/users', (req, res) => {
  // Mask sensitive information in response using configurable domain
  const users = config.data.exampleUsers.map(user => ({
    ...user,
    email: `${user.name.charAt(0)}***${config.data.emailDomainMask}`
  }));

  res.json(users);
});

// ======================
// ERROR HANDLING
// ======================

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.originalUrl} not found`,
    environment: config.server.environment
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(`[ERROR] ${req.method} ${req.originalUrl}:`, err);

  const isProduction = config.server.environment === 'production';

  res.status(err.status || 500).json({
    error: isProduction ? 'Internal Server Error' : err.message,
    message: isProduction ? 'Something went wrong' : err.stack,
    ...(isProduction ? {} : { 
      stack: config.server.environment === 'development' ? err.stack : undefined 
    })
  });
});

// ======================
// SERVER STARTUP
// ======================
app.listen(config.server.port, config.server.host, () => {
  console.log(`🚀 Server running on http://${config.server.host}:${config.server.port}`);
  console.log(`📁 Environment: ${config.server.environment}`);
  console.log(`🔒 CORS Origin: ${config.security.corsOrigin}`);
  console.log(`⏱️  Rate Limit: ${config.security.rateLimit.max} requests per ${config.security.rateLimit.windowMs / (60 * 1000)} minutes`);

  if (config.server.environment === 'development') {
    console.log('🔧 Development mode: /config endpoint available');
  }
});

module.exports = app;

