const fs = require('fs');
const http = require('http');

// Read the vault-audit.txt file
const vaultAuditContent = fs.readFileSync('vault-audit.txt', 'utf8');

// Parse the file into a structured format
function parseVaultAudit(content) {
  const lines = content.split('\n');
  const result = {
    metadata: {
      generated: new Date().toISOString(),
      source: 'vault-audit.txt',
      purpose: 'Cross-reference with production vault'
    },
    synthetic_values: [],  // From .env.test
    placeholder_values: [], // From .env.example
    raw_content: content
  };

  let currentSection = null;

  for (const line of lines) {
    // Skip empty lines and pure comment lines
    if (!line.trim() || line.trim().startsWith('#') && !line.includes('=')) {
      // Check for section headers
      if (line.includes('.env.test') && line.includes('Synthetic/Canary')) {
        currentSection = 'synthetic';
      } else if (line.includes('.env.example') && line.includes('Placeholder')) {
        currentSection = 'placeholder';
      }
      continue;
    }

    // Parse key=value pairs
    if (line.includes('=')) {
      const [key, ...valueParts] = line.split('=');
      const value = valueParts.join('='); // In case value contains '='

      const entry = {
        key: key.trim(),
        value: value.trim(),
        source: currentSection === 'synthetic' ? '.env.test' : '.env.example',
        type: currentSection === 'synthetic' ? 'synthetic_canary' : 'placeholder_instructional'
      };

      if (currentSection === 'synthetic') {
        result.synthetic_values.push(entry);
      } else if (currentSection === 'placeholder') {
        result.placeholder_values.push(entry);
      }
    }
  }

  return result;
}

// Create JSON payload
const payload = parseVaultAudit(vaultAuditContent);

// Configure HTTP request
const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/vault-check',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(JSON.stringify(payload))
  }
};

console.log('Sending vault audit data to http://localhost:3003/api/vault-check');
console.log(`Payload contains:`);
console.log(`- ${payload.synthetic_values.length} synthetic/canary values`);
console.log(`- ${payload.placeholder_values.length} placeholder values`);
console.log('');

// Make the request
const req = http.request(options, (res) => {
  let responseData = '';

  console.log(`Response Status: ${res.statusCode} ${res.statusMessage}`);
  console.log(`Response Headers: ${JSON.stringify(res.headers, null, 2)}`);

  res.setEncoding('utf8');
  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('\nResponse Body:');
    try {
      const parsedResponse = JSON.parse(responseData);
      console.log(JSON.stringify(parsedResponse, null, 2));
    } catch (e) {
      console.log(responseData);
    }
  });
});

req.on('error', (e) => {
  console.error(`Request error: ${e.message}`);
});

// Write data to request body
req.write(JSON.stringify(payload));
req.end();

